begin;
do $$
declare u uuid:='00000000-0000-0000-0000-0000000000e9'; outro uuid:='00000000-0000-0000-0000-0000000000ea'; a uuid;b uuid;t uuid;r jsonb; linha uuid; chave uuid:=gen_random_uuid();
begin
 insert into auth.users(id) values(u),(outro);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);
 a:=(public.criar_conta_bancaria('Conta A',10000,'2026-10-01')->>'id')::uuid;
 b:=(public.criar_conta_bancaria('Conta B',0,'2026-10-01')->>'id')::uuid;
 perform public.transferir_entre_contas(a,b,2500,'2026-10-02',chave);
 perform public.transferir_entre_contas(a,b,2500,'2026-10-02',chave);
 if (select count(*) from public.movimentos_conta where user_id=u)<>2 then raise exception 'transferência duplicada';end if;
 if (select sum(valor) from public.movimentos_conta where user_id=u)<>0 then raise exception 'dinheiro criado';end if;
 if exists(select 1 from public.transacoes_origem where user_id=u) then raise exception 'transferência virou gasto';end if;
 begin perform public.transferir_entre_contas(a,b,3000,'2026-10-02',chave);raise exception 'chave reutilizada com dados diferentes';exception when sqlstate 'FW409' then null;end;
 begin perform public.transferir_entre_contas(a,b,2500,'2026-09-30',gen_random_uuid());raise exception 'data anterior';exception when sqlstate 'FW400' then null;end;
 perform public.importar_extrato_conta(a,'OFX','[{"data":"2026-10-03","valor":-1200,"descricao":"MERCADO","id_externo":"X1"}]');
 perform public.importar_extrato_conta(a,'OFX','[{"data":"2026-10-03","valor":-1200,"descricao":"MERCADO","id_externo":"X1"}]');
 if (select count(*) from public.linhas_extrato_conta where conta_id=a)<>1 then raise exception 'extrato duplicado';end if;
 select id into linha from public.linhas_extrato_conta where conta_id=a;
 if exists(select 1 from public.transacoes_origem where user_id=u) then raise exception 'staging criou gasto';end if;
 t:=(public.processar_transacao_completa('MERCADO',1200,'DESPESA','DEBITO',null,'2026-10-03',1)->>'transacao_id')::uuid;
 perform public.conciliar_linha_conta(linha,'VINCULAR',t,null,null);
 perform public.conciliar_linha_conta(linha,'VINCULAR',t,null,null);
 if (select count(*) from public.transacoes_origem where user_id=u and deleted_at is null)<>1 then raise exception 'conciliação duplicou gasto';end if;
 begin update public.transacoes_origem set valor_total=1300 where id=t;raise exception 'edição de conciliada';exception when sqlstate 'FW409' then null;end;
 begin perform public.fechar_conciliacao_conta(a,'2026-10-03',999);raise exception 'saldo divergente fechado';exception when sqlstate 'FW409' then null;end;
 perform public.importar_extrato_conta(a,'CSV','[{"data":"2026-10-02","valor":-2500,"descricao":"PIX PRÓPRIO"}]');
 perform public.conciliar_linha_conta((select id from public.linhas_extrato_conta where conta_id=a and valor=-2500),'TRANSFERENCIA',null,(select id from public.movimentos_conta where conta_id=a and transferencia_id=chave),null);
 perform public.fechar_conciliacao_conta(a,'2026-10-03',6300);
 begin perform public.desfazer_conciliacao_conta(linha);raise exception 'período fechado alterado';exception when sqlstate 'FW409' then null;end;
 perform public.reabrir_conciliacao_conta(a,'Conferir lançamento');
 perform public.desfazer_conciliacao_conta(linha);
 perform public.conciliar_linha_conta(linha,'VINCULAR',t,null,null);
 perform public.importar_extrato_conta(b,'CSV','[{"data":"2026-10-02","valor":2500,"descricao":"PIX PRÓPRIO"},{"data":"2026-10-02","valor":2500,"descricao":"PIX PRÓPRIO"}]');
 if (select count(*) from public.linhas_extrato_conta where conta_id=b)<>2 then raise exception 'compras iguais perdidas';end if;
 perform public.importar_extrato_conta(b,'CSV','[{"data":"2026-10-02","valor":2500,"descricao":"PIX PRÓPRIO"},{"data":"2026-10-02","valor":2500,"descricao":"PIX PRÓPRIO"}]');
 if (select count(*) from public.linhas_extrato_conta where conta_id=b)<>2 then raise exception 'compras iguais repetidas';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outro)::text,true);
 begin perform public.importar_extrato_conta(a,'CSV','[]');raise exception 'extrato cruzado';exception when sqlstate 'FW404' then null;end;
 begin perform public.consultar_conta_bancaria(a,'2026-10-01','2026-10-31');raise exception 'consulta cruzada';exception when sqlstate 'FW404' then null;end;
 if has_table_privilege('authenticated','public.movimentos_conta','insert') or has_function_privilege('anon','public.criar_conta_bancaria(text,bigint,date)','execute') then raise exception 'permissões';end if;
 raise notice 'OK: 17/17 asserts contas, transferência, importação, conciliação, fechamento e isolamento';
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-0000000000ea"}',true);
do $$ begin
 if exists(select 1 from public.contas_bancarias) or exists(select 1 from public.movimentos_conta) or exists(select 1 from public.linhas_extrato_conta) or exists(select 1 from public.historico_conciliacao) then raise exception 'RLS bancária deixou vazar dados';end if;
end $$;
rollback;
